contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0));

        uint256 balTargetBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 balSenderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        c.mintToken(target, mintedAmount); if (__ESBMC_reverted()) return;

        uint256 balTargetAfter = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 balSenderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(balTargetAfter == balTargetBefore + mintedAmount);
    }

    receive() external payable {}
}

